};

class Solution {
    private long gcd(long a, long b) {
        while (b != 0) {
            long t = b;
            b = a % b;
            a = t;
        }
        return a;
    }
    public long interchangeableRectangles(int[][] rectangles) {
        Map<String, Long> freq = new HashMap<>();
        for (int[] r : rectangles) {
            long g = gcd(r[0], r[1]);
            String key = (r[0] / g) + ":" + (r[1] / g);
            freq.put(key, freq.getOrDefault(key, 0L) + 1L);
        }
        long ans = 0;
        for (long count : freq.values()) {
            ans += count * (count - 1) / 2;
        }
        return ans;
    }
}

function gcd(a, b) {
  while (b !== 0) {
    let t = b;
    b = a % b;
    a = t;
  }
  return a;
}

var interchangeableRectangles = function(rectangles) {
  const map = new Map();
  for (const [w, h] of rectangles) {
    const g = gcd(w, h);
    const key = `${w / g}:${h / g}`;
    map.set(key, (map.get(key) || 0) + 1);
  }
  let ans = 0;
  for (const cnt of map.values()) {
    ans += (cnt * (cnt - 1)) / 2;
  }
  return ans;
};
